<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('inventory.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); try{db()->beginTransaction(); $no=next_code('ADJ','stock_adjustments','adjustment_no'); q('INSERT INTO stock_adjustments(branch_id,adjustment_no,reason,notes,created_by,created_at) VALUES(?,?,?,?,?,NOW())',[$bid,$no,$_POST['reason'],trim($_POST['notes']??''),$_SESSION['user_id']]); $adjId=(int)db()->lastInsertId(); foreach($_POST['product_id']??[] as $i=>$pid){$pid=(int)$pid;$qty=(float)($_POST['quantity_change'][$i]??0); if($pid&&$qty!=0){q('INSERT INTO stock_adjustment_items(adjustment_id,product_id,quantity_change) VALUES(?,?,?)',[$adjId,$pid,$qty]); stock_move($bid,$pid,$qty,$_POST['reason']==='internal_use'?'internal_use':'adjustment','adjustment',$adjId,$_POST['reason']);}} audit('create','stock_adjustments',$adjId); db()->commit(); flash('success','Stock adjustment saved.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack(); flash('error',$e->getMessage());} redirect('modules/stock_adjustments.php');}
$rows=all('SELECT * FROM stock_adjustments WHERE branch_id=? ORDER BY id DESC LIMIT 100',[$bid]); $title='Stock Adjustment'; $subtitle='Damage, expired, lost, correction and internal use adjustments with audit trail.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><h2>New Adjustment</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Reason</label><select name="reason" required><option value="damage">Damage</option><option value="expired">Expired</option><option value="lost">Lost</option><option value="correction">Correction</option><option value="internal_use">Internal Use</option><option value="opening">Opening</option></select></div><div class="form-group"><label>Notes</label><input name="notes"></div></div><div id="lines"><div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity_change[]" placeholder="+ add / - reduce"><span></span><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div></div><button type="button" class="btn secondary" onclick="addLine()">+ Add Line</button> <button class="btn">Save Adjustment</button></form></section><script>function addLine(){document.querySelector('#lines').insertAdjacentHTML('beforeend',`<div class="cart-row"><select name="product_id[]"><option value="">Product</option><?php foreach(product_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select><input type="number" step="0.001" name="quantity_change[]" placeholder="+ add / - reduce"><span></span><button type="button" class="btn small danger" onclick="this.parentElement.remove()">×</button></div>`)}</script><h2>Recent Adjustments</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>No</th><th>Reason</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['adjustment_no'])?></td><td><?=e($r['reason'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>